import {ADVANCED_UNITS,RUBRIC,advancedUnit} from './advanced_content.mjs?v=advanced20261103';
import {readAdvanced,patchAdvanced,startAdvancedAttempt,recordAdvancedAnswer,annotateAdvancedAudio,attemptScore,saveAdvancedDraft,scheduleAdvancedReview,advancedSummary} from './advanced_progress.mjs?v=advanced20261103';
import {readMasterclass,countEnglishWords} from './masterclass.mjs?v=advanced20261103';
import * as sound from './quest/sound.mjs?v=joy20261103';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const speechState=new Map();
let feedback=null,notice='',currentRoute='';
const getStore=()=>{try{return globalThis.localStorage;}catch{return null;}};
const url=(id='',stage='learn')=>`#advanced${id?`/${id}/${stage}`:''}`;
const dateLabel=n=>new Date(n).toLocaleDateString('zh-TW');
const STAGES=[['learn','看懂觀念'],['practice','獨立檢核'],['write','初稿與修訂'],['review','隔天再練']];
function route(){const parts=(globalThis.location?.hash||'#advanced').slice(1).split('/');return {id:ADVANCED_UNITS.some(u=>u.id===parts[1])?parts[1]:'',stage:STAGES.some(([id])=>id===parts[2])?parts[2]:'learn'};}
function sourcePanel(u,form='practice',hide=false){
 const sources=form==='transfer'&&u.transferSources?u.transferSources:u.sources,key=`${u.id}:${form}`,state=speechState.get(key)||{};
 return `<section class="advanced-sources" aria-label="${hide?'聽力報告':'任務來源'}"><div class="advanced-source-actions"><span>${hide?'先聽立場，再做筆記':'任務來源 · 本站原創情境'}</span><div><button type="button" data-advanced-speak="${form}">▶ 聽英文</button><button type="button" data-advanced-speak="${form}" data-slow="1">慢速</button><button type="button" data-advanced-stop>停止</button></div></div>${hide?`<p class="advanced-note">使用裝置合成語音。完整播放且本組未開逐字稿才標示為盲聽；無法播放時，可看稿完成文字輔助練習。</p><button class="advanced-text-button" type="button" data-advanced-transcript="${form}">${state.transcript?'隱藏逐字稿（本組開稿紀錄仍保留）':'需要文字支援？顯示逐字稿'}</button>`:''}<p role="status" id="advanced-audio-status">${state.heard?'✓ 已完成播放。':state.message?esc(state.message):''}</p>${!hide||state.transcript?`<div class="advanced-source-grid">${sources.map(([title,body])=>`<article><h3>${esc(title)}</h3><p lang="en">${esc(body)}</p></article>`).join('')}</div>`:'<div class="advanced-listen-placeholder" aria-label="逐字稿已隱藏">♫<p>聽兩段，記下：立場／證據／限制／下一步</p></div>'}</section>`;
}
function badges(s){return [['觀念探索者',s.read>=1],['證據偵探',s.checks>=3],['修訂實踐者',s.revised>=1],['作品集同行者',s.loops===8]].map(([name,earned])=>`<span class="advanced-badge ${earned?'earned':''}">${earned?'✦':'◇'} ${name}<small>${earned?'已取得':'尚未取得'}</small></span>`).join('');}
function dashboard(store){const s=advancedSummary(store);return `<section class="advanced-dashboard"><div class="advanced-hero"><div><p class="home-label">ADVANCED ENGLISH / THINK · EXPLAIN · REVISE</p><h1>C1 → C2 精進課程</h1><p class="home-intro">不只選出答案，更能整合、說清楚，<br>再把自己的第一稿變好。</p><a class="home-btn primary" href="${url(s.next)}">${s.due?'接續到期複習':'開始／接續我的課程'} →</a></div><div class="advanced-evidence"><span class="home-tag">我的學習證據</span><strong>${s.loops}<small> / 8 個學習循環</small></strong><meter min="0" max="8" value="${s.loops}" aria-label="完成教學、檢核與修訂的單元數"></meter><p>看過教學 ${s.read} · 做完檢核 ${s.checks}<br>留下修訂 ${s.revised} · 到期複習 ${s.due}</p><small>這是完成紀錄，不是 CEFR 程度分數。</small></div></div><div class="advanced-course-facts"><span><b>8</b> 能力單元</span><span><b>48</b> 原創檢核題</span><span><b>4</b> 作品自評面向</span><span><b>2</b> 初稿／修訂版本</span></div><p class="advanced-boundary">以高階能力為目標的自學模組；不是完整 C2 認證課程。作品與口說品質仍需要教師或同儕回饋。你可以自由選單元。</p><div class="advanced-badges" aria-label="學習流程徽章">${badges(s)}</div><section aria-labelledby="advanced-map-title"><div class="home-section-heading"><div><p class="home-label">YOUR COURSE MAP</p><h2 id="advanced-map-title">從讀懂觀點，到提出自己的觀點。</h2></div><a class="home-text-link" href="#masterclass">查看原本四份作品草稿 →</a></div><ol class="advanced-map">${ADVANCED_UNITS.map(u=>{const row=s.rows.find(r=>r.id===u.id);return `<li><a href="${url(u.id)}"><div><span class="advanced-unit-number">0${u.number}</span><span aria-hidden="true">${u.icon}</span></div><small>${u.skill} · 約 ${u.minutes} 分鐘</small><h3>${u.title}</h3><p>${u.canDo}</p><span class="advanced-map-status">${row.loop?'✓ 已留下完整循環紀錄':row.revised?'✎ 已留下修訂':row.practice?'✓ 已做檢核':row.read?'✓ 已讀教學':'開始這一單元 →'}</span></a></li>`;}).join('')}</ol></section></section>`;}
function lesson(u,r){return `<section class="advanced-lesson"><p class="home-tag">本單元可以做到</p><h2>${u.canDo}</h2>${u.lesson.map(p=>`<p>${esc(p)}</p>`).join('')}<figure class="advanced-diagram"><div>${u.diagram.map(([term,label],i)=>`<span><b lang="en">${esc(term)}</b><small>${esc(label)}</small></span>${i<2?'<i aria-hidden="true">→</i>':''}`).join('')}</div><figcaption>先抓關係，再檢查來源與自己的表達。</figcaption></figure><div class="concept-table-wrap" tabindex="0" role="region" aria-label="${u.title}策略對照表"><table><caption>${u.title} · 策略對照</caption><thead><tr><th scope="col">重點</th><th scope="col">語句／線索</th><th scope="col">怎麼用</th></tr></thead><tbody>${u.table.map(row=>`<tr><th scope="row">${esc(row[0])}</th><td>${esc(row[1])}</td><td>${esc(row[2])}</td></tr>`).join('')}</tbody></table></div>${sourcePanel(u,'practice',!!u.listening)}<div class="advanced-task-brief"><h3>你的作品任務</h3><p>${u.target}</p><ol>${u.steps.map(s=>`<li>${s}</li>`).join('')}</ol></div><button type="button" class="home-btn primary" data-advanced-read>${r.read?'再看一次，前往檢核':'我已閱讀，開始獨立檢核'} →</button></section>`;}
function explanation(item,selected){return `<div class="advanced-feedback ${selected===item.answer?'good':''}" role="status"><strong>${selected===item.answer?'✓ 判斷正確':selected===-1?'一起看證據':'再看一次判斷依據'}</strong><p>正解：${esc(item.options[item.answer])}</p><p>${esc(item.why)}</p></div>`;}
function quiz(u,r,form){
 const bank=u[form==='transfer'?'transfer':'checks'],active=r.active,last=r.attempts?.filter(a=>a.form===form).at(-1);
 if(active&&active.form!==form)return `<div class="advanced-empty"><h2>還有一組未完成的檢核</h2><p>已保存 ${active.answers.length} / 3 題。先接續它，再開另一組。</p><a class="home-btn primary" href="${url(u.id,active.form==='transfer'?'review':'practice')}">接續作答 →</a></div>`;
 const audio=u.listening?sourcePanel(u,form,true):form==='practice'?sourcePanel(u):'';
 if(!active&&!last)return `${audio}<div class="advanced-quiz-intro"><span class="home-tag">${form==='transfer'?'第二組遷移檢核':'第一組觀念檢核'} · 3 題</span><h2>${form==='transfer'?'換一個情境，還能判斷嗎？':'先獨立判斷，再對照證據。'}</h2><p>選項順序會變化。可以選「還不會」先學解說；只記錄每題第一次回答，不發闖關 XP。</p><button type="button" class="home-btn primary" data-advanced-start="${form}">開始這 3 題 →</button></div>`;
 if(!active){const score=attemptScore(u.id,last),modality=u.listening?(last.heard&&!last.transcript?'已完成播放、未開逐字稿的聽力練習':'文字輔助／未完成播放；不列為獨立盲聽'):'';return `<section class="advanced-quiz-result"><span class="home-tag">本次第一次回答</span><h2 tabindex="-1">${score} / 3 題</h2><p>${modality||'這組題目用來找補強方向，不推算整體程度。'}</p><div class="advanced-result-list">${bank.map((item,i)=>`<article><h3>${i+1}. ${esc(item.prompt)}</h3><p class="advanced-note">你的回答：${last.answers[i]===-1?'還不會':esc(item.options[last.answers[i]])}</p>${explanation(item,last.answers[i])}</article>`).join('')}</div><div class="advanced-button-row"><a class="home-btn primary" href="${url(u.id,'write')}">用到自己的作品裡 →</a><button type="button" class="home-btn secondary" data-advanced-start="${form}">再練同一組</button></div><p class="advanced-note">重練會保留本次紀錄（最近 8 次）；不宣稱重練是未見題。</p></section>`;}
 const showing=feedback?.run===active.id&&feedback.index===active.answers.length-1,index=showing?feedback.index:active.answers.length,item=bank[index],chosen=showing?active.answers[index]:null;
 return `${audio}<section class="advanced-quiz"><div class="warmup-progress"><span>${form==='transfer'?'遷移檢核':'觀念檢核'}</span><b>${index+1} / 3</b></div><progress value="${index}" max="3" aria-label="本組已完成題數"></progress><h2 tabindex="-1">${esc(item.prompt)}</h2><div class="advanced-options">${active.orders[index].map((value,i)=>`<button type="button" data-advanced-answer="${value}" data-run="${esc(active.id)}" data-index="${index}" ${showing?'disabled':''} class="${showing&&value===item.answer?'correct':showing&&value===chosen?'incorrect':''}"><span>${String.fromCharCode(65+i)}</span><b>${esc(item.options[value])}</b>${showing&&value===item.answer?'<small>✓ 正解</small>':''}</button>`).join('')}</div>${showing?`${explanation(item,chosen)}<button type="button" class="home-btn primary" data-advanced-next>下一題 →</button>`:`<button type="button" class="advanced-text-button" data-advanced-answer="-1" data-run="${esc(active.id)}" data-index="${index}">還不會，先看解析</button>`}</section>`;
}
function editor(u,r,store){const legacy=readMasterclass(store)[u.id],draft=r.scratch||r.revision||r.initial||{text:typeof legacy?.text==='string'?legacy.text:'',note:'',ratings:[0,0,0,0]},rs=draft.ratings||[0,0,0,0];
 return `<section class="advanced-editor"><span class="home-tag">先完成，再修好</span><h2>讓自己的作品往前走一步。</h2><p>${u.target}</p>${!r.initial&&legacy?.text?'<p class="advanced-import-note">已帶入原作品工坊草稿；原紀錄保留不變，按「保留初稿」建立這裡的版本。</p>':''}<details class="advanced-reference"><summary>回看來源與三步任務</summary>${sourcePanel(u,'practice',!!u.listening)}<ol>${u.steps.map(s=>`<li>${s}</li>`).join('')}</ol></details><label for="advanced-draft">我的英文作品</label><textarea id="advanced-draft" rows="11" maxlength="12000" lang="en" placeholder="先用自己的話寫，再看示範。">${esc(draft.text)}</textarea><div class="advanced-editor-meta"><span><b id="advanced-wordcount">${countEnglishWords(draft.text)}</b> 個英文詞 · 只作長度提醒</span><span id="advanced-scratch-status" role="status">草稿會自動儲存在此瀏覽器。</span></div><div class="advanced-criteria"><h3>這份作品的四個檢查點</h3><ol>${u.criteria.map(c=>`<li>${c}</li>`).join('')}</ol></div><fieldset class="advanced-rubric"><legend>四維自評 · 不是自動品質評分</legend>${RUBRIC.map((dimension,i)=>`<label for="advanced-rating-${i}"><b>${dimension.title}</b><select id="advanced-rating-${i}" data-advanced-rating="${i}">${['尚未自評','1 · 仍需協助','2 · 發展中','3 · 大致達成','4 · 表現穩健'].map((label,n)=>`<option value="${n}" ${rs[i]===n?'selected':''}>${label}</option>`).join('')}</select><small>${rs[i]?esc(dimension.levels[rs[i]-1]):'先讀下面的評量規準，再判斷。'}</small></label>`).join('')}</fieldset><details class="advanced-reference"><summary>展開四維規準與程度差異</summary><div class="concept-table-wrap" tabindex="0" role="region" aria-label="作品自評規準"><table><caption>本站練習用描述，不換算 CEFR</caption><thead><tr><th scope="col">面向</th>${[1,2,3,4].map(n=>`<th scope="col">${n}</th>`).join('')}</tr></thead><tbody>${RUBRIC.map(d=>`<tr><th scope="row">${d.title}</th>${d.levels.map(l=>`<td>${l}</td>`).join('')}</tr>`).join('')}</tbody></table></div></details><label for="advanced-revision-note">我改了什麼，為什麼？</label><textarea id="advanced-revision-note" rows="3" maxlength="2000" placeholder="例如：刪掉『全部學生』，因為來源只訪問社團成員；把限制移到建議前。">${esc(draft.note)}</textarea><div class="advanced-button-row"><button type="button" class="home-btn secondary" data-advanced-save="initial" ${r.initial?'disabled':''}>${r.initial?'✓ 初稿已保留':'保留這份初稿'}</button><button type="button" class="home-btn primary" data-advanced-save="revision">另存修訂稿</button><button type="button" class="home-btn secondary" data-advanced-export>下載初稿與修訂</button></div><p class="advanced-note">修訂稿需與初稿不同、有至少 6 字修改理由及四項自評。初稿不會被覆蓋；最多保留 3 份先前修訂。語言品質請再找教師或同儕核對。</p>${r.initial?`<details class="advanced-reference"><summary>查看已保留的初稿${r.revision?'與最新修訂':''}</summary><div class="advanced-draft-compare"><section><h3>初稿 · ${dateLabel(r.initial.at)}</h3><p lang="en">${esc(r.initial.text)}</p></section>${r.revision?`<section><h3>修訂 · ${dateLabel(r.revision.at)}</h3><p lang="en">${esc(r.revision.text)}</p><small>修改理由：${esc(r.revision.note)}</small></section>`:''}</div></details>`:''}<details class="advanced-reference"><summary>自己寫過，再看示範策略</summary><p class="advanced-model" lang="en">${esc(u.model)}</p><p>${u.focus}</p></details></section>`;
}
function review(u,r){const latest=r.attempts?.filter(a=>a.form==='transfer').at(-1),ready=!!r.revision&&!!latest&&attemptScore(u.id,latest)>=2;return `<section class="advanced-review"><span class="home-tag">跨天再提取</span><h2>換情境檢查，再安排下次複習。</h2><p>先不看教學，用第二組不同題目重新判斷；做過之後可再次練習，但不再視為未見題。</p>${r.review?`<p class="advanced-import-note">已安排 ${dateLabel(r.review.due)} 再練 · ${r.review.days} 天間隔。這是練習排程，不是個人記憶模型。</p>`:''}${quiz(u,r,'transfer')}<div class="advanced-review-ratings"><h3>做完後，下一次何時再練？</h3><p class="advanced-note">「大致可以／很穩」需先留下修訂、且最近一份第二組檢核至少答對 2 題；同日重按不會增加間隔。</p><div class="advanced-button-row"><button type="button" class="home-btn secondary" data-advanced-review="again">還要練 · 隔天再來</button><button type="button" class="home-btn secondary" data-advanced-review="good" ${ready?'':'disabled'}>大致可以</button><button type="button" class="home-btn secondary" data-advanced-review="easy" ${ready?'':'disabled'}>很穩，安排稍後複習</button></div></div></section>`;}
export function renderAdvancedCourse(hash){const info=hash?(()=>{const p=hash.replace(/^#/,'').split('/');return {id:ADVANCED_UNITS.some(u=>u.id===p[1])?p[1]:'',stage:STAGES.some(([s])=>s===p[2])?p[2]:'learn'};})():route(),store=getStore(),state=readAdvanced(store),u=info.id?advancedUnit(info.id):null,r=u?state.units[u.id]||{}:{};
 const routeKey=`${info.id}:${info.stage}`;if(currentRoute!==routeKey){notice='';feedback=null;currentRoute=routeKey;}
 return `<article class="learning-hub home-experience advanced-academy" data-advanced-unit="${u?.id||''}" data-advanced-stage="${info.stage}"><nav class="advanced-breadcrumb" aria-label="課程位置"><a href="#home">← 學習首頁</a>${u?'<a href="#advanced">全部 8 單元</a>':'<a href="#masterclass">原作品工坊</a>'}</nav>${u?`<header class="advanced-unit-header"><p class="home-label">UNIT 0${u.number} / ${u.skill}</p><h1>${u.title}</h1><p>${u.level} 目標 · 約 ${u.minutes} 分鐘 · ${r.read?'✓ 已讀教學':'從這裡開始'}</p></header><nav class="advanced-stage-nav" aria-label="本單元四步學習">${STAGES.map(([id,label],i)=>`<a href="${url(u.id,id)}" ${id===info.stage?'aria-current="step"':''}><span>0${i+1}</span>${label}</a>`).join('')}</nav><p id="advanced-notice" class="advanced-notice" role="status">${esc(notice)}</p><div class="advanced-workbench">${info.stage==='practice'?quiz(u,r,'practice'):info.stage==='write'?editor(u,r,store):info.stage==='review'?review(u,r):lesson(u,r)}</div><nav class="advanced-unit-pager" aria-label="單元切換">${u.number>1?`<a href="${url(ADVANCED_UNITS[u.number-2].id)}">← 上一單元</a>`:'<a href="#advanced">← 課程地圖</a>'}${u.number<8?`<a href="${url(ADVANCED_UNITS[u.number].id)}">下一單元 →</a>`:'<a href="#advanced">回顧我的作品紀錄 →</a>'}</nav>`:dashboard(store)}<p class="home-source-note">學習目標參考 <a href="https://www.coe.int/en/web/common-european-framework-reference-languages/cefr-descriptors" target="_blank" rel="noopener noreferrer">CEFR 能力描述</a>；作品規準參考 <a href="https://www.cambridgeenglish.org/Images/168194-c2-proficiency-teachers-handbook.pdf" target="_blank" rel="noopener noreferrer">Cambridge C2 教師手冊</a>的評閱面向，描述由本站重新撰寫。所有題材為本站原創，不是官方試題。進度、草稿與排程只保存在本瀏覽器，已納入首頁學習護照的全站備份。</p></article>`;
}
function portfolioText(u,r){return `${u.title}\n\n任務：${u.target}\n\n初稿：\n${r.initial?.text||'尚未保留'}\n\n最新修訂：\n${r.revision?.text||'尚未保留'}\n\n修改理由：\n${r.revision?.note||''}\n\n四維自評（不等於 CEFR 分數）：\n${RUBRIC.map((d,i)=>`${d.title}：${r.revision?.ratings?.[i]||0}/4`).join('\n')}\n\n來源：本站原創情境；請教師或同儕回饋。`;}
const bindings=new WeakMap();
export function disposeAdvancedCourse(root){bindings.get(root)?.();bindings.delete(root);}
export function bindAdvancedCourse(root,render=()=>{root.querySelector('.main').innerHTML=renderAdvancedCourse();bindAdvancedCourse(root);}){
 disposeAdvancedCourse(root);const el=root.querySelector('.advanced-academy');if(!el)return;
 const id=el.dataset.advancedUnit,stage=el.dataset.advancedStage,controller=new AbortController(),signal=controller.signal;let pending=null,timer;
 const flush=()=>{clearTimeout(timer);if(!pending)return;const ok=patchAdvanced(id,{scratch:pending});pending=null;const status=root.querySelector('#advanced-scratch-status');if(status)status.textContent=ok?'✓ 草稿已自動儲存。':'無法自動儲存，請先複製文字或下載作品。';};
 const capture=()=>{const input=root.querySelector('#advanced-draft');if(!input)return null;return {text:input.value,note:root.querySelector('#advanced-revision-note').value,ratings:[...root.querySelectorAll('[data-advanced-rating]')].map(s=>Number(s.value))};};
 const redraw=()=>{flush();render();};
 bindings.set(root,()=>{flush();controller.abort();sound.stop();});
 window.addEventListener('pagehide',flush,{signal});
 root.addEventListener('input',e=>{if(!e.target.matches('#advanced-draft,#advanced-revision-note'))return;pending=capture();const wordCount=root.querySelector('#advanced-wordcount');if(wordCount)wordCount.textContent=countEnglishWords(pending.text);root.querySelector('#advanced-scratch-status').textContent='正在儲存草稿…';clearTimeout(timer);timer=setTimeout(flush,400);},{signal});
 root.addEventListener('change',e=>{if(!e.target.matches('[data-advanced-rating]'))return;pending=capture();const n=Number(e.target.dataset.advancedRating),value=Number(e.target.value);e.target.parentElement.querySelector('small').textContent=value?RUBRIC[n].levels[value-1]:'先讀下面的評量規準，再判斷。';flush();},{signal});
 root.addEventListener('click',async event=>{
  const anchor=event.target.closest('a');if(anchor){flush();sound.stop();feedback=null;notice='';return;}
  const b=event.target.closest('button');if(!b||b.disabled)return;const d=b.dataset;if(!Object.keys(d).some(k=>k.startsWith('advanced')))return;
  const store=getStore(),u=advancedUnit(id),r=readAdvanced(store).units[id]||{};
  if('advancedRead'in d){if(patchAdvanced(id,{read:true},store))location.hash=url(id,'practice');else{notice='無法儲存進度，請確認瀏覽器儲存空間。';redraw();}return;}
  if(d.advancedStart){const form=d.advancedStart;feedback=null;notice='';const audio=speechState.get(`${id}:${form}`)||{};if(!startAdvancedAttempt(id,form,store,{heard:audio.heard,transcript:audio.transcript||audio.seenText}))notice='尚有其他組檢核未完成，或目前無法儲存作答。';redraw();return;}
  if('advancedAnswer'in d){const next=recordAdvancedAnswer(id,d.run,Number(d.index),Number(d.advancedAnswer),store);if(next){if(next.answers.length===3)speechState.delete(`${id}:${next.form}`);feedback={run:next.id,index:next.answers.length-1};notice='';redraw();root.querySelector('[data-advanced-next],.advanced-quiz-result h2')?.focus({preventScroll:true});}else{notice='作答未儲存；請確認儲存空間或重新整理以載入最新進度。';redraw();}return;}
  if('advancedNext'in d){feedback=null;redraw();root.querySelector('.advanced-quiz h2')?.focus({preventScroll:true});return;}
  if(d.advancedSave){const draft=capture();flush();const result=saveAdvancedDraft(id,draft.text,d.advancedSave,draft.note,draft.ratings,store);notice=result.message;redraw();return;}
  if(d.advancedReview){const next=scheduleAdvancedReview(id,d.advancedReview,store);notice=next?`✓ 已安排 ${dateLabel(next.due)} 再練（${next.days} 天後）。`:'請先留下修訂並完成最近的第二組檢核至少 2/3；若已完成，請確認儲存空間。';redraw();return;}
  if('advancedExport'in d){flush();const current=readAdvanced(store).units[id]||{},draft=capture();const body=portfolioText(u,current)+(draft?`\n\n目前編輯區草稿：\n${draft.text}`:'');const blob=new Blob([body],{type:'text/plain;charset=utf-8'}),fileURL=URL.createObjectURL(blob),a=document.createElement('a');a.href=fileURL;a.download=`english-quest-${id}-portfolio.txt`;a.click();setTimeout(()=>URL.revokeObjectURL(fileURL),1000);return;}
  if(d.advancedTranscript){const form=d.advancedTranscript,key=`${id}:${form}`,audio=speechState.get(key)||{};speechState.set(key,{...audio,transcript:!audio.transcript,seenText:audio.seenText||!audio.transcript});if(!audio.transcript&&r.active?.form===form)annotateAdvancedAudio(id,r.active.id,{transcript:true},store);redraw();return;}
  if('advancedStop'in d){sound.stop();const status=root.querySelector('#advanced-audio-status');if(status)status.textContent='已停止播放；未完成播放不記為聽力證據。';return;}
  if(d.advancedSpeak){const form=d.advancedSpeak,key=`${id}:${form}`,audio=speechState.get(key)||{},run=r.active?.form===form?r.active.id:null;const status=root.querySelector('#advanced-audio-status');if(status)status.textContent='正在播放英文…';const sources=form==='transfer'&&u.transferSources?u.transferSources:u.sources;const result=await sound.speak(sources.map(s=>s[1]).join('\n\n'),{slow:d.slow==='1'});if(signal.aborted)return;const current=speechState.get(key)||audio;if(result==='ok'){speechState.set(key,{...current,heard:true,message:'✓ 已完成播放。'});if(run)annotateAdvancedAudio(id,run,{heard:true},store);}const box=root.querySelector('#advanced-audio-status');if(box)box.textContent=result==='ok'?'✓ 已完成播放。':result==='stopped'?'播放已停止，這次未記完整播放。':'目前語音不可用，可以開啟逐字稿繼續練習。';}
 },{signal});
}
